 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    # Each nonzero connected component is one nested-color object.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))

            bounds = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in bounds:
                    bounds[color] = [y, y, x, x]
                else:
                    b = bounds[color]
                    b[0] = min(b[0], y)
                    b[1] = max(b[1], y)
                    b[2] = min(b[2], x)
                    b[3] = max(b[3], x)

            # Nested layers have progressively smaller bounding boxes.
            layers = sorted(bounds, key=lambda color: (
                (bounds[color][1] - bounds[color][0] + 1) *
                (bounds[color][3] - bounds[color][2] + 1),
                bounds[color][1] - bounds[color][0] + bounds[color][3] - bounds[color][2]
            ), reverse=True)
            recolor = {old: layers[len(layers) - 1 - i] for i, old in enumerate(layers)}
            for y, x in cells:
                out[y][x] = recolor[grid[y][x]]
    return out

